SELECT jsonb_build_object(
'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'schema',n.nspname,'name',p.proname,'hash',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'owner',pg_get_userbyid(p.proowner),'sd',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'acl',p.proacl::text,'arguments',pg_get_function_arguments(p.oid)) ORDER BY n.nspname,p.proname,p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='rating_validation_b3b' OR (n.nspname='public' AND p.proname IN ('capture_rating_validation_snapshot','finalize_rating_validation_seal','capture_native_rating_validation_snapshot','finalize_native_rating_validation_seal'))),
'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='rating_validation_b3b'::regnamespace AND c.relkind='r'),
'policies',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY tablename,policyname),'[]') FROM pg_policies x WHERE schemaname='rating_validation_b3b'),
'constraints',(SELECT jsonb_agg(jsonb_build_object('table',k.conrelid::regclass::text,'name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY k.conrelid::regclass::text,k.conname) FROM pg_constraint k WHERE k.connamespace='rating_validation_b3b'::regnamespace),
'indexes',(SELECT jsonb_agg(to_jsonb(x) ORDER BY indexname) FROM pg_indexes x WHERE schemaname='rating_validation_b3b'),
'triggers',(SELECT jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgrelid::regclass::text,t.tgname) FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgrelid IN(SELECT c.oid FROM pg_class c WHERE c.relnamespace='rating_validation_b3b'::regnamespace)),
'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE c.relnamespace='rating_validation_b3b'::regnamespace AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped),
'schema_acl',(SELECT nspacl::text FROM pg_namespace WHERE nspname='rating_validation_b3b'));
